  if (cU1.length > 3) labs.push(labelSpec(cU1, 'Image of u = u₀ + Δu'));
  if (cV1.length > 3) labs.push(labelSpec(cV1, 'Image of v = v₀ + Δv'));
  if (cV0.length > 3) labs.push(labelSpec(cV0, 'Image of v = v₀'));
  placeLabels(g, labs);

  /* overlay */
  if (st.overlay && parOk) {
    var pPx = par.map(function (p) { return [rx(p[0]), ry(p[1])]; });
    g.polygon(ptsAttr(pPx)).fill('none')
      .stroke({ color: C_ORANGE, width: 2, linejoin: 'round' }).attr('stroke-dasharray', '6,4');
    drawVec(g, pPx[0], pPx[1], C_ORANGE, '(∂r/∂u)Δu');
    drawVec(g, pPx[0], pPx[3], C_MAG, '(∂r/∂v)Δv');
    g.circle(8).center(pPx[0][0], pPx[0][1]).fill('#333');

    var bx = RB.x0 + 4, by = RB.y1 - 76;
    var box = g.rect(206, 74).move(bx, by).radius(5)
      .fill({ color: '#ffffff', opacity: 0.9 }).stroke({ color: '#cdd8e0', width: 1 });
    box.css('cursor', 'pointer').on('click', function () {
      showPopup('Why the Jacobian is the area factor',
        'The vectors (∂r/∂u)Δu and (∂r/∂v)Δv are the linear approximations of the two edges of R at T(u₀,v₀). ' +
        'The parallelogram they span has area |xu·yv − xv·yu|·ΔuΔv = |J|·ΔuΔv, and as Δu,Δv → 0 this matches area(R) exactly.');
    });
    var ty0 = by + 18, lh = 16;
    mkText(g, 'area(S) = ΔuΔv = ' + areaS.toFixed(4), bx + 9, ty0, 12.5, { anchor: 'start', italic: false, halo: false });
    mkText(g, 'area(R) = ' + areaR.toFixed(4), bx + 9, ty0 + lh, 12.5, { anchor: 'start', italic: false, halo: false });
    mkText(g, 'area(R)/area(S) = ' + (areaR / areaS).toFixed(4), bx + 9, ty0 + 2 * lh, 12.5, { anchor: 'start', italic: false, halo: false });
    mkText(g, '|J(u₀,v₀)| = ' + Math.abs(jac.J).toFixed(4), bx + 9, ty0 + 3 * lh, 12.5, { anchor: 'start', italic: false, halo: false, fill: C_ORANGE });
  }

  updateReadout(areaS, areaR, jac.J);
}

function drawVec(g, p0, p1, color, label) {
  var ang = Math.atan2(p1[1] - p0[1], p1[0] - p0[0]);
  var L = Math.hypot(p1[0] - p0[0], p1[1] - p0[1]);
  if (L < 3) return;
  var hs = Math.min(12, Math.max(6, L * 0.3));
  g.line(p0[0], p0[1], p1[0] - Math.cos(ang) * hs * 0.6, p1[1] - Math.sin(ang) * hs * 0.6)
    .stroke({ color: color, width: 2.6, linecap: 'round' });
  arrowHead(g, p1[0], p1[1], ang, hs, color);
  var mx = (p0[0] + p1[0]) / 2 - Math.sin(ang) * 14, my = (p0[1] + p1[1]) / 2 + Math.cos(ang) * 14;
  mkText(g, label, mx, my, 12, { anchor: 'middle', italic: false, fill: color });
}

function updateReadout(areaS, areaR, J) {
  var el = document.getElementById('jacReadout');
  if (!el) return;
  el.innerHTML =
    '(u₀,v₀) = (' + st.u0.toFixed(2) + ', ' + st.v0.toFixed(2) + ')<br>' +
    'Δu = ' + st.du.toFixed(2) + ', Δv = ' + st.dv.toFixed(2) + '<br>' +
    'area(S) = ' + areaS.toFixed(4) + '<br>' +
    'area(R) = ' + (isFinite(areaR) ? areaR.toFixed(4) : '—') + '<br>' +
    'ratio&nbsp;&nbsp;&nbsp; = ' + (isFinite(areaR) ? (areaR / areaS).toFixed(4) : '—') + '<br>' +
    '|J(u₀,v₀)| = ' + (isFinite(J) ? Math.abs(J).toFixed(4) : '—');
}

/* ================= focus veil + master redraw ================= */
function drawFocus() {
  if (st.focus === 'left') gRoot.rect(496, 336).move(6, 2).radius(10).fill('#eef7fd').stroke('none');
  if (st.focus === 'right') gRoot.rect(458, 336).move(658, 2).radius(10).fill('#eef7fd').stroke('none');
}
function redraw() {
  if (!st.fx || !st.fy) return;
  gRoot.clear();
  drawFocus();
  drawLeft();
  drawArrow();
  drawRight();
}

