var stepIdx = 0, tweenId = 0;

function tweenU0(target, ms) {
  var s0 = st.u0, t0 = (window.performance ? performance.now() : Date.now()), id = ++tweenId;
  function fr(t) {
    if (id !== tweenId) return;
    var k = Math.min(1, (t - t0) / ms);
    st.u0 = s0 + (target - s0) * (k * k * (3 - 2 * k));
    redraw();
    if (k < 1) requestAnimationFrame(fr);
  }
  requestAnimationFrame(fr);
}

function applyStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  var s = STEPS[stepIdx].s;
  tweenId++;
  st.overlay = s.ov;
  var cb = document.getElementById('showJacobianInput'); if (cb) cb.checked = s.ov;
  st.du = s.cell; st.dv = s.cell;
  var sl = document.getElementById('cellSizeInput'), o = document.getElementById('cellSizeVal');
  if (sl) sl.value = s.cell; if (o) o.value = s.cell.toFixed(2);
  st.u0 = s.u0; st.v0 = s.v0; st.focus = s.focus;
  var xi = document.getElementById('xExprInput'), yi = document.getElementById('yExprInput');
  if (xi && xi.value !== s.x) { xi.value = s.x; bindX.apply(s.x); }
  if (yi && yi.value !== s.y) { yi.value = s.y; bindY.apply(s.y); }
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + STEPS[stepIdx].t;
  document.getElementById('demoNarration').textContent = STEPS[stepIdx].n;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + ' / ' + STEPS.length;
  redraw();
  if (s.tween != null) tweenU0(s.tween, 900);
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

